$(document).ready(function(){var e=new Array,t=document.getElementsByClassName("codemirror");if(t.length>0)for(var n=0;n<t.length;n++){var r=CodeMirror.fromTextArea(t[n],{lineNumbers:!0,lineWrapping:!0,styleActiveLine:!0,matchBrackets:!0,mode:"markdown",htmlMode:!0,indentUnit:4,theme:"tomorrow-night-bright",extraKeys:{F11:function(e){e.setOption("fullScreen",!e.getOption("fullScreen"))},Esc:function(e){e.getOption("fullScreen")&&e.setOption("fullScreen",!1)}}});r.setSize("100%",500),e.push(r)}});